def chip_score(row):
    return sum(w * _get(row, k) for k, w in CHIP_WEIGHTS.items())
def _get(row, col):
    try:
        v = row[col]
    except (KeyError, IndexError):
        return 0
    return 0 if v is None else v
def status(h, s):
    """依**事先宣告**的條件判定,不臨場解釋。

    門檻取 `stats_ci.t_threshold(eff_obs)`(MC 校準,隨有效獨立觀測分級)——
    固定 1.96 在這種樣本量下的實際誤判率是 10~24%,不是 5%。
    """
    if not s:
        return "尚無資料"
    if s.get("se_blocked") or s["eff_obs"] < h["min_eff_obs"]:
        return f"累積中(需有效獨立觀測 ≥ {h['min_eff_obs']:.0f},現 {s['eff_obs']:.1f})"
    t, thr = s["t"], sci.t_threshold(s["eff_obs"])
    want = 1 if h["direction"] == "positive" else -1
    if t is not None and t * want >= thr:
        return f"**達成宣告的成功條件**(門檻 {thr:.1f})"
    if t is not None and t * want <= -thr:
        return f"**反向成立 → 依宣告放棄**(門檻 {thr:.1f})"
    if s["eff_obs"] >= 30:
        return "**無訊號 → 依宣告放棄**"
    return f"累積中(尚未達判定門檻 {thr:.1f})"
def nw_se(series, lag):
    """Newey-West 標準誤(Bartlett kernel)。series = 每個交易日一個數。

    lag=0 時退化為一般標準誤。回傳 None 表示樣本不足以估計。
    """
    x = [v for v in series if v is not None]
    n = len(x)
    if n < 3:
        return None
    m = statistics.mean(x)
    e = [v - m for v in x]
    s = sum(v * v for v in e) / n                      # gamma_0
    for L in range(1, min(int(lag), n - 1) + 1):
        g = sum(e[i] * e[i - L] for i in range(L, n)) / n
        s += 2 * (1 - L / (lag + 1)) * g               # Bartlett 權重
    return (max(s, 0.0) / n) ** 0.5
def summarize(daily, fwd, dates_used=None, all_dates=None):
    """一次算齊判讀強度。daily = 每個交易日一個數(例:當日各族群 IC 的平均)。

    有效獨立觀測不足時**刻意不回報 SE 與 t**——寧可顯示「樣本不足」,
    也不要給一個會被當成證據的假數字。
    """
    x = [v for v in daily if v is not None]
    if not x:
        return None
    lag = overlap_lag(fwd)
    eff = effective_obs(len(x), fwd)
    m = statistics.mean(x)
    se = nw_se(x, lag) if eff >= MIN_EFF_OBS else None
    return {
        "mean": m, "se": se, "t": (m / se) if se else None,
        "n_days": len(x), "lag": lag, "eff_obs": eff,
        "se_blocked": eff < MIN_EFF_OBS,
        "ac1": autocorr1(x),
        "episodes": (episodes(dates_used, all_dates)
                     if dates_used is not None and all_dates is not None else None),
    }
